const select =                    (id        )           => document.querySelector   (`#${id}`);
const status = select             ("server-status"), diagnostics = select             ("diagnostics"), canvas = select                   ("sprite-canvas");
const objectSelect = select                   ("object-select"), frameSelect = select                   ("frame-select"), seek = select                  ("timeline-seek"), loop = select                  ("loop-enabled"), playButton = select                   ("play-toggle"), fields = select             ("frame-fields");
let project                          , tickIndex = 0, playing = false, timer                    , stateToken = "", tokenHeader = "x-dat-skill-flow-token";
const images = new Map                          ();
const record = (value         )       => value !== null && typeof value === "object" ? value         : {};
const list = (value         )            => Array.isArray(value) ? value : [];
const text = (value         )         => typeof value === "string" ? value : "";
const number = (value         , fallback = 0)         => typeof value === "number" && Number.isFinite(value) ? value : fallback;

async function request(path        , init              , stateChanging = false)                {
    const headers                         = { Accept: "application/json", ...(init?.headers                           ?? {}) };
    if (stateChanging) { headers["Content-Type"] = "application/json"; if (stateToken) headers[tokenHeader] = stateToken; }
    const response = await fetch(path, { ...init, headers }); const body = record(await response.json());
    if (!response.ok) throw new Error(text(body.message) || `${response.status} ${path}`); return body;
}
function normalize(payload      )               {
    const data = record(payload.data), session = record(data.document ?? data.session ?? data.project ?? data), projection = record(session.projection ?? data.projection);
    const preview = record(session.nativePreview ?? session.preview ?? session.trace ?? data.nativePreview ?? data.preview ?? data.trace);
    const frames = list(projection.frames ?? session.frames).map((value, index) => ({ ...record(value), frameId: number(record(value).frameId ?? record(value).id, index) }));
    const assets = new Map                ();
    for (const value of list(session.assets ?? session.spriteAssets ?? data.assets ?? data.spriteAssets)) { const asset = record(value); const id = text(asset.assetId ?? asset.id); if (id) assets.set(text(asset.file), id); }
    const fallbackAsset = text(session.assetId ?? data.assetId); if (fallbackAsset) assets.set("", fallbackAsset);
    const fieldIds = new Map                ();
    for (const value of list(session.fields ?? data.fields)) { const field = record(value), id = text(field.fieldId ?? field.id); if (id) fieldIds.set(`${number(field.frameId)}:${text(field.key)}`, id); }
    const ticks = list(preview.ticks ?? preview.nativeTicks ?? session.ticks).map((value) => { const raw = record(value); return { ...raw, cameraX: number(raw.camera_x ?? raw.cameraX), entities: list(raw.entities).map((entity) => { const item = record(entity); return { ...item, oid: number(item.oid), frame: number(item.frame), x: number(item.x), y: number(item.y), z: number(item.z) }; }) }; });
    return { sessionId: text(session.sessionId ?? data.sessionId), revision: (session.revision ?? data.revision ?? "-")                   , name: text(session.name ?? data.name ?? "Project"), dirty: session.dirty === true || data.dirty === true, frames, ranges: list(projection.spriteRanges ?? session.spriteRanges ?? data.spriteRanges).map(record), nativeTicks: ticks, assets, fieldIds };
}
function currentFrame()                    { const primary = project?.nativeTicks[tickIndex]?.entities.find((entity) => entity.oid === 2) ?? project?.nativeTicks[tickIndex]?.entities[0]; return project?.frames.find((frame) => frame.frameId === primary?.frame) ?? project?.frames[0]; }
function update()       { const frame = currentFrame(), count = project?.nativeTicks.length ?? 0; select             ("tick-readout") .textContent = String(tickIndex); select             ("frame-readout") .textContent = frame ? String(frame.frameId) : "-"; select             ("time-readout") .textContent = `${tickIndex * 33} ms`; if (seek) { seek.max = String(Math.max(0, count - 1)); seek.value = String(tickIndex); } if (playButton) { playButton.textContent = playing ? "Pause" : "Play"; playButton.ariaPressed = String(playing); } draw(); }
function loadImage(assetId        )                   { let image = images.get(assetId); if (!image) { image = new Image(); image.src = `/api/assets/${encodeURIComponent(assetId)}`; image.onload = update; images.set(assetId, image); } return image; }
function draw()       { const context = canvas?.getContext("2d"), tick = project?.nativeTicks[tickIndex]; if (!canvas || !context) return; context.clearRect(0, 0, canvas.width, canvas.height); if (!tick || !project) { context.fillText("No native preview ticks returned.", 20, 30); return; } for (const entity of tick.entities) { const frame = project.frames.find((candidate) => candidate.frameId === entity.frame), pic = number(frame?.pic ?? entity.pic, 999); const range = project.ranges.find((candidate) => pic >= number(candidate.frameLo ?? candidate.frame_lo) && pic <= number(candidate.frameHi ?? candidate.frame_hi, -1)); const x = Math.round(canvas.width / 2 + entity.x - tick.cameraX), y = Math.round(canvas.height - 110 - entity.y - entity.z * .5); const assetId = range === undefined ? undefined : (text(range.assetId) || project.assets.get(text(range.file)) || project.assets.get("")); if (!range || !assetId || pic === 999) { context.strokeStyle = "#f4b34b"; context.strokeRect(x - 12, y - 24, 24, 24); context.fillText(`OID ${entity.oid} F${entity.frame}`, x - 24, y - 30); continue; } const w = number(range.w), h = number(range.h), cols = number(range.row); if (w <= 0 || h <= 0 || cols <= 0) continue; const local = pic - number(range.frameLo ?? range.frame_lo); const image = loadImage(assetId); context.imageSmoothingEnabled = false; context.drawImage(image, (local % cols) * (w + 1), Math.floor(local / cols) * (h + 1), w, h, x, y - h, w, h); } }
function render()       { if (!project) return; frameSelect?.replaceChildren(...project.frames.map((frame) => { const option = document.createElement("option"); option.value = String(frame.frameId); option.textContent = `#${frame.frameId} pic ${number(frame.pic)}`; return option; })); renderFields(); update(); }
function renderFields()       { fields?.replaceChildren(); const frame = currentFrame(); if (!frame || !fields) return; for (const [key, value] of Object.entries(frame)) { if (typeof value !== "number" || key === "frameId") continue; const label = document.createElement("label"), input = document.createElement("input"); label.textContent = key; input.name = key; input.type = "number"; input.value = String(value); label.append(input); fields.append(label); } }
async function preview(startFrame        )                { if (!project) return; const response = await request("/api/project/preview", { method: "POST", body: JSON.stringify({ sessionId: project.sessionId, expectedRevision: project.revision, startFrame, ticks: 180 }) }, true); project = normalize(response); tickIndex = 0; render(); }
function step()       { const last = Math.max(0, (project?.nativeTicks.length ?? 1) - 1); tickIndex = tickIndex >= last ? (loop?.checked ? 0 : last) : tickIndex + 1; update(); }
function schedule()       { if (!playing || timer !== undefined) return; timer = window.setTimeout(() => { timer = undefined; step(); schedule(); }, 33); }
async function open(objectKey        , oid        )                { const response = await request("/api/project/open", { method: "POST", body: JSON.stringify({ objectKey }) }, true); project = normalize(response); tickIndex = 0; status .textContent = `Loaded ${project.name} / OID ${oid}`; select             ("session-name") .textContent = project.name; select             ("revision-readout") .textContent = `revision ${project.revision}`; select             ("dirty-readout") .textContent = project.dirty ? "dirty" : "clean"; render(); }
async function start()                { try { const bootstrap = record((await request("/api/bootstrap")).data), security = record(bootstrap.security); stateToken = text(security.token ?? bootstrap.stateToken ?? bootstrap.token); tokenHeader = text(security.tokenHeader ?? bootstrap.tokenHeader) || tokenHeader; const listing = record((await request("/api/project")).data); const choices = list(listing.objects ?? listing.entries); objectSelect?.replaceChildren(...choices.map((value) => { const item = record(value), oid = number(item.oid), objectKey = text(item.objectKey); const option = document.createElement("option"); option.value = objectKey; option.dataset.oid = String(oid); option.textContent = `OID ${oid} ${text(item.name)}`; option.selected = oid === 2; return option; })); const selected = objectSelect?.selectedOptions[0]; await open(objectSelect?.value || "", number(selected?.dataset.oid, 2)); } catch (error) { status .textContent = "Project unavailable"; diagnostics .textContent = error instanceof Error ? error.message : "Project load failed."; } }
objectSelect?.addEventListener("change", () => { const option = objectSelect.selectedOptions[0]; void open(objectSelect.value, number(option?.dataset.oid)); }); frameSelect?.addEventListener("change", () => void preview(Number(frameSelect.value))); seek?.addEventListener("input", () => { tickIndex = Number(seek.value); update(); }); playButton?.addEventListener("click", () => { playing = !playing; update(); schedule(); }); select("step-once")?.addEventListener("click", step); select("reset-timeline")?.addEventListener("click", () => { tickIndex = 0; update(); });
select                 ("frame-editor")?.addEventListener("submit", (event) => { event.preventDefault(); const form = new FormData(event.currentTarget), entry = [...form.entries()][0], frame = currentFrame(); if (!entry || !project || !frame) return; const fieldId = project.fieldIds.get(`${frame.frameId}:${entry[0]}`); if (!fieldId) { diagnostics .textContent = `No editable field id for ${entry[0]}.`; return; } void request("/api/project/edit", { method: "POST", body: JSON.stringify({ sessionId: project.sessionId, fieldId, value: Number(entry[1]), expectedRevision: project.revision }) }, true).then((response) => { project = normalize(response); return preview(frame.frameId); }).catch((error) => diagnostics .textContent = String(error)); });
select("save-project")?.addEventListener("click", () => project && void request("/api/project/save", { method: "POST", body: JSON.stringify({ sessionId: project.sessionId, expectedRevision: project.revision }) }, true).then(() => diagnostics .textContent = "Save requested.").catch((error) => diagnostics .textContent = String(error)));
for (const key of ["a", "d", "j", "Fj", "Fa", "Da", "Ua", "ja", "Dj", "Uj"]) select(`hit-${key.toLowerCase()}`)?.addEventListener("click", () => { const target = number(currentFrame()?.[`hit_${key}`]); if (target >= 0) void preview(target); });
void start();
